  /**
   * allVirtualNumbersOutgoings iterates over GET /v1/sms/{serviceName}/virtualNumbers/{number}/outgoing (List sent SMS).
   *
   * It lists the IDs with {@link SmsApi.listVirtualNumbersOutgoings}, then gets each object with
   * {@link SmsApi.getVirtualNumbersOutgoing}, only when the loop reaches it. An object deleted in the
   * meantime is skipped. Any other error is thrown and stops the loop.
   *
   * The two calls require the IAM action sms:apiovh:virtualNumbers/outgoing/get.
   *
   * @param serviceName - The internal name of your SMS offer
   * @param number - The virtual number
   * @param params - the optional parameters
   * @param options - the options of this call: signal, timeout, headers
   * @returns each {@link models.SmsOutgoing}, one at a time: loop with `for await`
   * @throws ForbiddenError when the policy lacks an IAM action this call requires
   * @example
   * for await (const item of client.sms.allVirtualNumbersOutgoings(serviceName, number)) console.log(item);
   */
  allVirtualNumbersOutgoings(
    serviceName: string,
    number: string,
    params?: {
      /** Filter the value of creationDatetime property (>=) */
      creationDatetimeFrom?: string | undefined;
      /** Filter the value of creationDatetime property (<=) */
      creationDatetimeTo?: string | undefined;
      /** Filter the value of deliveryReceipt property (=) */
      deliveryReceipt?: number | undefined;
      /** Filter the value of differedDelivery property (=) */
      differedDelivery?: number | undefined;
      /** Filter the value of ptt property (=) */
      ptt?: number | undefined;
      /** Filter the value of receiver property (=) */
      receiver?: string | undefined;
      /** Filter the value of sender property (=) */
      sender?: string | undefined;
      /** Filter the value of tag property (=) */
      tag?: string | undefined;
    },
    options?: RequestOptions,
  ): AsyncIterable<models.SmsOutgoing> {
    return this._each(
      () => this.listVirtualNumbersOutgoings(serviceName, number, params, options),
      (listedId) => this.getVirtualNumbersOutgoing(serviceName, number, listedId, options),
    );
  }

